<?php
namespace Tests\Feature;
use Tests\TestCase;
use App\Models\User;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class CanteenTest extends TestCase {
 use DatabaseTransactions;
 private function fixture():array {$c=DB::table('communication_companies')->insertGetId(['name'=>'Canteen Test Company','created_at'=>now(),'updated_at'=>now()]);$other=DB::table('communication_companies')->insertGetId(['name'=>'Other Test Company','created_at'=>now(),'updated_at'=>now()]);$u=User::create(['name'=>'Canteen Employee','email'=>Str::uuid().'@example.test','password'=>'LongTestPassword123!','is_active'=>true,'company_id'=>$c]);$u->forceFill(['is_active'=>true,'status'=>1,'company_id'=>$c])->save();DB::table('user_product_access')->insert(['user_id'=>$u->id,'product_slug'=>'canteen']);DB::table('communication_company_memberships')->insert(['user_id'=>$u->id,'company_id'=>$c]);$level=DB::table('canteen_levels')->insertGetId(['company_id'=>$c,'name'=>'Level 1','company_percent'=>50]);$profile=DB::table('canteen_profiles')->insertGetId(['company_id'=>$c,'user_id'=>$u->id,'level_id'=>$level,'role'=>'employee','eligible'=>true]);$category=DB::table('canteen_categories')->insertGetId(['company_id'=>$c,'name'=>'Tea & Coffee']);$item=DB::table('canteen_items')->insertGetId(['company_id'=>$c,'category_id'=>$category,'name'=>'Chai','price'=>100,'stock_enabled'=>true,'stock_quantity'=>10]);DB::table('canteen_item_rules')->insert(['item_id'=>$item,'level_id'=>$level,'quantity_limit'=>3,'period'=>'day']);DB::table('canteen_settings')->insert(['company_id'=>$c,'within_allowance_mode'=>'free','excess_mode'=>'level_share','ordering_enabled'=>true]);return compact('c','other','u','level','profile','category','item');}
 private function payload(array $f,int $quantity=1,?string $key=null):array {$body=['company_id'=>$f['c'],'request_key'=>$key??(string)Str::uuid(),'lines'=>[['item_id'=>$f['item'],'quantity'=>$quantity]]];$body['quote_token']=$this->postJson('/canteen/api/quote',$body)->json('quote_token')??str_repeat('0',64);return $body;}
 public function test_items_outside_level_benefits_are_visible_and_fully_employee_paid():void {
  $f=$this->fixture();$this->actingAs($f['u']);
  DB::table('canteen_item_rules')->where('item_id',$f['item'])->delete();
  $this->getJson('/canteen/api/catalog?company_id='.$f['c'])->assertOk()->assertJsonFragment(['name'=>'Chai']);
  foreach(['level_share','full_price','block'] as $policy){
   DB::table('canteen_settings')->where('company_id',$f['c'])->update(['excess_mode'=>$policy]);
   $body=$this->payload($f,2);
   $this->postJson('/canteen/api/quote',$body)->assertOk()->assertJsonPath('gross',200)->assertJsonPath('company_share',0)->assertJsonPath('employee_share',200)->assertJsonPath('lines.0.allowance_quantity',0);
  }
  $id=$this->postJson('/canteen/api/orders',$body)->assertCreated()->json('order.id');
  $this->assertDatabaseHas('canteen_orders',['id'=>$id,'company_share'=>0,'employee_share'=>200]);
  $this->assertDatabaseHas('canteen_items',['id'=>$f['item'],'stock_quantity'=>8]);
 }
 public function test_shared_account_creation_supports_all_three_products_and_canteen_role():void {$this->seed(\App\Modules\Pms\Database\Seeders\PmsFoundationSeeder::class);$f=$this->fixture();$role=DB::table('pms_roles')->where('role_key','employee')->value('id');$email=Str::uuid().'@example.test';$this->withSession(['judibas_admin'=>true])->postJson('/admin/api/users',['name'=>'Shared Employee','email'=>$email,'password'=>'LongTestPassword123!','is_active'=>true,'product_slugs'=>['communication','projects','canteen'],'company_ids'=>[$f['c']],'pms_role_ids'=>[$role],'canteen_role'=>'cashier'])->assertOk();$id=User::where('email',$email)->value('id');foreach(['communication','projects','canteen'] as $slug)$this->assertDatabaseHas('user_product_access',['user_id'=>$id,'product_slug'=>$slug]);$this->assertDatabaseHas('canteen_profiles',['company_id'=>$f['c'],'user_id'=>$id,'role'=>'cashier']);}
 public function test_central_invitation_keeps_canteen_access_and_role():void {$f=$this->fixture();$response=$this->withSession(['judibas_admin'=>true])->postJson('/admin/api/invitations',['name'=>'Kitchen Staff','email'=>Str::uuid().'@example.test','product_slugs'=>['canteen'],'company_ids'=>[$f['c']],'canteen_role'=>'kitchen','delivery_method'=>'manual'])->assertCreated();$row=DB::table('platform_invitations')->where('email','!=','')->orderByDesc('id')->first();$access=json_decode($row->access,true);$this->assertEquals(['canteen'],$access['product_slugs']);$this->assertEquals('kitchen',$access['canteen_role']);$this->assertNotEmpty($response->json('invitation_url'));}
 public function test_employee_access_company_isolation_and_no_admin_mutations():void {$f=$this->fixture();$this->getJson('/canteen/api/bootstrap')->assertForbidden();$this->actingAs($f['u'])->getJson('/canteen/api/bootstrap')->assertOk()->assertJsonCount(1,'companies');$this->getJson('/canteen/api/catalog?company_id='.$f['other'])->assertForbidden();$this->postJson('/canteen/api/catalog/levels',['company_id'=>$f['c'],'name'=>'Escalated','company_percent'=>100,'active'=>true])->assertForbidden();$this->getJson('/canteen/api/reports?company_id='.$f['c'].'&from=2026-10-01&to=2026-10-31')->assertForbidden();DB::table('user_product_access')->where('user_id',$f['u']->id)->delete();$this->getJson('/canteen/api/bootstrap')->assertForbidden();}
 public function test_allowance_split_idempotency_and_stock_are_preserved():void {$f=$this->fixture();$this->actingAs($f['u']);$body=$this->payload($f,4);$this->postJson('/canteen/api/quote',$body)->assertOk()->assertJsonPath('gross',400)->assertJsonPath('company_share',350)->assertJsonPath('employee_share',50);$response=$this->postJson('/canteen/api/orders',$body)->assertCreated();$id=$response->json('order.id');$this->assertDatabaseHas('canteen_items',['id'=>$f['item'],'stock_quantity'=>6]);$this->postJson('/canteen/api/orders',$body)->assertCreated()->assertJsonPath('order.id',$id);$this->assertEquals(1,DB::table('canteen_orders')->where('request_key',$body['request_key'])->count());$this->assertDatabaseHas('canteen_items',['id'=>$f['item'],'stock_quantity'=>6]);$this->postJson('/canteen/api/orders',$this->payload($f,3,$body['request_key']))->assertStatus(409);$this->postJson('/canteen/api/quote',$this->payload($f))->assertOk()->assertJsonPath('employee_share',50);DB::table('canteen_items')->where('id',$f['item'])->update(['price'=>200]);$this->get('/canteen/orders/'.$id.'/receipt/cashier')->assertOk()->assertSee('50.00',false);$this->assertDatabaseHas('canteen_order_lines',['order_id'=>$id,'unit_price'=>100]);}
 public function test_stock_and_eligibility_rejections_have_no_partial_orders():void {$f=$this->fixture();$this->actingAs($f['u']);$this->postJson('/canteen/api/orders',$this->payload($f,11))->assertUnprocessable();$this->assertEquals(0,DB::table('canteen_orders')->where('company_id',$f['c'])->count());$this->assertDatabaseHas('canteen_items',['id'=>$f['item'],'stock_quantity'=>10]);DB::table('canteen_profiles')->where('id',$f['profile'])->update(['eligible'=>false]);$this->postJson('/canteen/api/orders',$this->payload($f))->assertUnprocessable();}
 public function test_cashier_cancellation_restores_stock_and_allowance_and_kitchen_hides_financials():void {$f=$this->fixture();$this->actingAs($f['u']);$id=$this->postJson('/canteen/api/orders',$this->payload($f,2))->assertCreated()->json('order.id');DB::table('canteen_profiles')->where('id',$f['profile'])->update(['role'=>'kitchen']);$this->getJson('/canteen/api/orders?company_id='.$f['c'])->assertOk()->assertJsonMissingPath('data.0.employee_share')->assertJsonMissingPath('data.0.lines.0.unit_price');$this->get('/canteen/orders/'.$id.'/receipt/cashier')->assertForbidden();$this->patchJson('/canteen/api/orders/'.$id,['payment_status'=>'paid'])->assertForbidden();$this->patchJson('/canteen/api/orders/'.$id,['status'=>'ready'])->assertUnprocessable();$this->patchJson('/canteen/api/orders/'.$id,['status'=>'preparing'])->assertOk();DB::table('canteen_profiles')->where('id',$f['profile'])->update(['role'=>'cashier']);$this->patchJson('/canteen/api/orders/'.$id,['status'=>'cancelled'])->assertOk();$this->assertDatabaseHas('canteen_items',['id'=>$f['item'],'stock_quantity'=>10]);$this->patchJson('/canteen/api/orders/'.$id,['status'=>'cancelled'])->assertUnprocessable();$this->assertDatabaseHas('canteen_items',['id'=>$f['item'],'stock_quantity'=>10]);$this->assertEquals(0,\App\Modules\Canteen\Services\Ordering::consumed($f['c'],$f['u']->id,$f['item'],'day'));}
 public function test_policy_variants_and_cross_company_level_validation():void {$f=$this->fixture();$this->actingAs($f['u']);DB::table('canteen_settings')->where('company_id',$f['c'])->update(['within_allowance_mode'=>'level_share']);$this->postJson('/canteen/api/quote',$this->payload($f,3))->assertOk()->assertJsonPath('employee_share',150);DB::table('canteen_settings')->where('company_id',$f['c'])->update(['within_allowance_mode'=>'free','excess_mode'=>'full_price']);$this->postJson('/canteen/api/quote',$this->payload($f,4))->assertOk()->assertJsonPath('employee_share',100);DB::table('canteen_settings')->where('company_id',$f['c'])->update(['excess_mode'=>'block']);$this->postJson('/canteen/api/orders',$this->payload($f,4))->assertUnprocessable();DB::table('canteen_profiles')->where('id',$f['profile'])->update(['role'=>'admin']);$bad=DB::table('canteen_levels')->insertGetId(['company_id'=>$f['other'],'name'=>'Other Level','company_percent'=>80]);$this->postJson('/canteen/api/catalog/profiles/'.$f['profile'],['company_id'=>$f['c'],'level_id'=>$bad,'eligible'=>true])->assertUnprocessable();}
 public function test_price_changes_require_a_new_quote_and_admin_catalog_saves_are_company_scoped():void {
  $f=$this->fixture();$this->actingAs($f['u']);$body=$this->payload($f);DB::table('canteen_items')->where('id',$f['item'])->update(['price'=>150]);$this->postJson('/canteen/api/orders',$body)->assertStatus(409);$this->assertEquals(0,DB::table('canteen_orders')->where('company_id',$f['c'])->count());
  DB::table('canteen_profiles')->where('id',$f['profile'])->update(['role'=>'admin']);
  $payload=['company_id'=>$f['c'],'name'=>'Chai','category_id'=>$f['category'],'price'=>150,'active'=>true,'stock_enabled'=>true,'stock_quantity'=>12,'expected_stock_quantity'=>10,'stock_reason'=>'New delivery','low_stock_threshold'=>4,'rules'=>[['level_id'=>$f['level'],'quantity_limit'=>4,'period'=>'week','company_percent'=>60,'item_id'=>999999]]];
  $this->postJson('/canteen/api/catalog/items/'.$f['item'],$payload)->assertOk();$this->assertDatabaseHas('canteen_item_rules',['item_id'=>$f['item'],'level_id'=>$f['level'],'quantity_limit'=>4,'period'=>'week','company_percent'=>60]);$this->assertDatabaseHas('canteen_stock_movements',['item_id'=>$f['item'],'quantity_change'=>2,'balance'=>12]);
  $this->postJson('/canteen/api/catalog/items/'.$f['item'],$payload)->assertStatus(409);$this->getJson('/canteen/api/catalog?company_id='.$f['c'])->assertOk();
 }
 public function test_reports_group_consumption_and_exports_apply_authorization():void {
  $f=$this->fixture();$this->actingAs($f['u']);$this->postJson('/canteen/api/orders',$this->payload($f,4))->assertCreated();DB::table('canteen_profiles')->where('id',$f['profile'])->update(['role'=>'admin']);$date=now()->setTimezone('Asia/Karachi')->toDateString();$query='company_id='.$f['c'].'&from='.$date.'&to='.$date;
  foreach(['item','category','employee','level','day'] as $group)$this->getJson('/canteen/api/reports?'.$query.'&group_by='.$group)->assertOk()->assertJsonPath('summary.orders',1)->assertJsonCount(1,'rows');
  $xlsx=$this->get('/canteen/api/reports/export/xlsx?'.$query)->assertOk()->assertHeader('Content-Type','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');$this->assertStringStartsWith('PK',$xlsx->streamedContent());
  $this->get('/canteen/api/reports/export/pdf?'.$query)->assertOk()->assertHeader('Content-Type','application/pdf');
  $this->getJson('/canteen/api/reports?'.$query.'&category_id=999999')->assertOk()->assertJsonPath('summary.orders',0);$this->getJson('/canteen/api/audit?company_id='.$f['c'])->assertOk();
 }
 public function test_invited_employee_accepts_canteen_using_existing_identity_flow():void {
  $f=$this->fixture();$email=Str::uuid().'@example.test';$response=$this->withSession(['judibas_admin'=>true])->postJson('/admin/api/invitations',['name'=>'Invited Canteen User','email'=>$email,'product_slugs'=>['canteen'],'company_ids'=>[$f['c']],'canteen_role'=>'employee','delivery_method'=>'manual'])->assertCreated();$token=basename($response->json('invitation_url'));$this->withSession(['judibas_admin'=>false])->postJson('/invitations/'.$token,['name'=>'Invited Canteen User','password'=>'LongTestPassword123!','password_confirmation'=>'LongTestPassword123!'])->assertOk();$user=User::where('email',$email)->first();$this->assertDatabaseHas('canteen_profiles',['user_id'=>$user->id,'company_id'=>$f['c'],'role'=>'employee']);$this->getJson('/canteen/api/bootstrap')->assertOk()->assertJsonCount(1,'companies');
 }
 public function test_paid_orders_cannot_be_cancelled_and_inventory_history_requires_admin():void {
  $f=$this->fixture();$this->actingAs($f['u']);DB::table('canteen_settings')->where('company_id',$f['c'])->update(['within_allowance_mode'=>'level_share']);$id=$this->postJson('/canteen/api/orders',$this->payload($f))->assertCreated()->json('order.id');$this->getJson('/canteen/api/stock?company_id='.$f['c'])->assertForbidden();DB::table('canteen_profiles')->where('id',$f['profile'])->update(['role'=>'cashier']);$this->patchJson('/canteen/api/orders/'.$id,['payment_status'=>'paid'])->assertOk();$this->patchJson('/canteen/api/orders/'.$id,['status'=>'cancelled'])->assertUnprocessable();$this->assertDatabaseHas('canteen_items',['id'=>$f['item'],'stock_quantity'=>9]);DB::table('canteen_profiles')->where('id',$f['profile'])->update(['role'=>'admin']);$this->getJson('/canteen/api/stock?company_id='.$f['c'])->assertOk()->assertJsonPath('data.0.quantity_change',-1);
 }
 public function test_employee_reports_preserve_levels_recorded_on_orders():void {
  $f=$this->fixture();$this->actingAs($f['u']);$this->postJson('/canteen/api/orders',$this->payload($f))->assertCreated();
  $next=DB::table('canteen_levels')->insertGetId(['company_id'=>$f['c'],'name'=>'Level 2','company_percent'=>60]);DB::table('canteen_item_rules')->insert(['item_id'=>$f['item'],'level_id'=>$next,'quantity_limit'=>3,'period'=>'day']);DB::table('canteen_profiles')->where('id',$f['profile'])->update(['level_id'=>$next]);$this->postJson('/canteen/api/orders',$this->payload($f))->assertCreated();DB::table('canteen_profiles')->where('id',$f['profile'])->update(['role'=>'admin']);$date=now()->setTimezone('Asia/Karachi')->toDateString();$query='company_id='.$f['c'].'&from='.$date.'&to='.$date;
  $rows=$this->getJson('/canteen/api/reports?'.$query)->assertOk()->assertJsonPath('group_by','employee')->assertJsonPath('summary.orders',2)->assertJsonCount(2,'rows')->json('rows');$this->assertEqualsCanonicalizing(['Level 1','Level 2'],array_column($rows,'level_name'));foreach($rows as $row)$this->assertSame('Canteen Employee',$row['label']);$this->get('/canteen/api/reports/export/pdf?'.$query)->assertOk();$xlsx=$this->get('/canteen/api/reports/export/xlsx?'.$query)->assertOk();$this->assertStringStartsWith('PK',$xlsx->streamedContent());
 }
 public function test_employee_product_rows_keep_quantities_and_order_totals_correct():void {
  $f=$this->fixture();$this->actingAs($f['u']);$water=DB::table('canteen_items')->insertGetId(['company_id'=>$f['c'],'category_id'=>$f['category'],'name'=>'Mineral Water','price'=>60,'stock_enabled'=>true,'stock_quantity'=>20]);DB::table('canteen_item_rules')->insert(['item_id'=>$water,'level_id'=>$f['level'],'quantity_limit'=>3,'period'=>'day']);$body=['company_id'=>$f['c'],'request_key'=>(string)Str::uuid(),'lines'=>[['item_id'=>$f['item'],'quantity'=>2],['item_id'=>$water,'quantity'=>3]]];$body['quote_token']=$this->postJson('/canteen/api/quote',$body)->assertOk()->json('quote_token');$this->postJson('/canteen/api/orders',$body)->assertCreated();DB::table('canteen_profiles')->where('id',$f['profile'])->update(['role'=>'admin']);$date=now()->setTimezone('Asia/Karachi')->toDateString();$query='company_id='.$f['c'].'&from='.$date.'&to='.$date;
  $response=$this->getJson('/canteen/api/reports?'.$query)->assertOk()->assertJsonCount(2,'rows')->assertJsonPath('summary.orders',1);$rows=collect($response->json('rows'))->keyBy('product_name');$this->assertEquals(2,$rows['Chai']['item_quantity']);$this->assertEquals(3,$rows['Mineral Water']['item_quantity']);$this->assertEquals(380,$response->json('summary.gross'));$this->assertEquals(380,$rows->sum('gross'));$this->getJson('/canteen/api/reports?'.$query.'&item_id='.$water)->assertOk()->assertJsonCount(1,'rows')->assertJsonPath('rows.0.product_name','Mineral Water');
 }
 public function test_detailed_reports_keep_separate_orders_and_export_all_pages():void {
  $f=$this->fixture();$this->actingAs($f['u']);$first=$this->postJson('/canteen/api/orders',$this->payload($f,2))->assertCreated()->json('order.id');$second=$this->postJson('/canteen/api/orders',$this->payload($f,1))->assertCreated()->json('order.id');DB::table('canteen_profiles')->where('id',$f['profile'])->update(['role'=>'admin']);$this->patchJson('/canteen/api/orders/'.$second,['status'=>'cancelled'])->assertOk();$date=now()->setTimezone('Asia/Karachi')->toDateString();$query='company_id='.$f['c'].'&from='.$date.'&to='.$date.'&group_by=order&user_id='.$f['u']->id;
  $rows=$this->getJson('/canteen/api/reports?'.$query)->assertOk()->assertJsonPath('total',2)->assertJsonPath('summary.orders',1)->assertJsonCount(2,'rows')->json('rows');$rows=collect($rows)->keyBy('order_id');$this->assertEquals(2,$rows[$first]['products'][0]['quantity']);$this->assertEquals(200,$rows[$first]['gross']);$this->assertSame('cancelled',$rows[$second]['status']);$this->assertEquals(0,$rows[$second]['gross']);$this->getJson('/canteen/api/reports?'.$query.'&user_id=999999')->assertOk()->assertJsonPath('total',0);
  $order=(array)DB::table('canteen_orders')->find($first);$line=(array)DB::table('canteen_order_lines')->where('order_id',$first)->first();unset($order['id'],$line['id']);for($n=0;$n<19;$n++){$order['request_key']=(string)Str::uuid();$id=DB::table('canteen_orders')->insertGetId($order);$line['order_id']=$id;DB::table('canteen_order_lines')->insert($line);}
  $this->getJson('/canteen/api/reports?'.$query)->assertOk()->assertJsonPath('total',21)->assertJsonCount(20,'rows');$this->getJson('/canteen/api/reports?'.$query.'&page=2')->assertOk()->assertJsonCount(1,'rows');$csv=$this->get('/canteen/api/reports/export/csv?'.$query.'&page=2')->assertOk()->streamedContent();$this->assertSame(22,count(array_filter(explode("\n",trim($csv)))));$this->assertStringContainsString('Chai x 2',$csv);$this->get('/canteen/api/reports/export/pdf?'.$query)->assertOk()->assertHeader('Content-Type','application/pdf');$xlsx=$this->get('/canteen/api/reports/export/xlsx?'.$query)->assertOk();$this->assertStringStartsWith('PK',$xlsx->streamedContent());
 }
 public function test_central_user_and_invitation_assign_company_specific_benefit_levels():void {
  $f=$this->fixture();$email=Str::uuid().'@example.test';$body=['name'=>'Benefits Employee','email'=>$email,'password'=>'LongTestPassword123!','is_active'=>true,'product_slugs'=>['canteen'],'company_ids'=>[$f['c']],'canteen_role'=>'employee','canteen_level_ids'=>[$f['c']=>$f['level']]];
  $this->withSession(['judibas_admin'=>true])->postJson('/admin/api/users',$body)->assertOk();$id=User::where('email',$email)->value('id');$this->assertDatabaseHas('canteen_profiles',['user_id'=>$id,'company_id'=>$f['c'],'level_id'=>$f['level']]);$this->getJson('/admin/api')->assertOk()->assertJsonFragment(['canteen_level_ids'=>[(string)$f['c']=>$f['level']]]);
  $bad=DB::table('canteen_levels')->insertGetId(['company_id'=>$f['other'],'name'=>'Other Company Level','company_percent'=>80]);$body['canteen_level_ids']=[$f['c']=>$bad];$this->postJson('/admin/api/users/'.$id,$body)->assertUnprocessable();$this->assertDatabaseHas('canteen_profiles',['user_id'=>$id,'level_id'=>$f['level']]);$body['canteen_level_ids']=[$f['c']=>null];$this->postJson('/admin/api/users/'.$id,$body)->assertOk();$this->assertDatabaseHas('canteen_profiles',['user_id'=>$id,'level_id'=>null]);
  $email=Str::uuid().'@example.test';$invite=$this->postJson('/admin/api/invitations',['name'=>'Invited Benefits Employee','email'=>$email,'product_slugs'=>['canteen'],'company_ids'=>[$f['c']],'canteen_role'=>'employee','canteen_level_ids'=>[$f['c']=>$f['level']],'delivery_method'=>'manual'])->assertCreated();$token=basename($invite->json('invitation_url'));$this->withSession(['judibas_admin'=>false])->postJson('/invitations/'.$token,['name'=>'Invited Benefits Employee','password'=>'LongTestPassword123!','password_confirmation'=>'LongTestPassword123!'])->assertOk();$id=User::where('email',$email)->value('id');$this->assertDatabaseHas('canteen_profiles',['user_id'=>$id,'company_id'=>$f['c'],'level_id'=>$f['level']]);
 }
